+    // *distinct* timestamps, which is the one arrangement that was already order-independent.
+    test('identical timestamps resolve by sys.id, not by input order', () => {
+      const alpha = entry('alpha', ['ZimmermannUS'], '2026-06-01T00:00:00.000Z');
