+      const beta = entry('beta', ['ZimmermannUS'], '2026-06-01T00:00:00.000Z');
+      pickMostSpecificByRegion([beta, alpha], 'ZimmermannUS');
+      expect(console.warn).toHaveBeenCalledTimes(1);
     });
   });
 });
