 1	/**
 2	 * Generic region-scoping resolution for Contentful entries carrying a `regions`
 3	 * reference field (see overrides/app/types/contentful.ts's RegionEntry / LinkEntry /
 4	 * FooterConfigEntry). Not footer-specific — works against any entry shaped this way.
 5	 *
 6	 * An entry with an omitted or empty `regions` array is the global/default case: it
 7	 * matches every site and is the *least* specific match. An entry scoping `regions` to
 8	 * fewer sites is more specific than one scoping it to more.
 9	 */
10	
11	type RegionRef = { fields: { siteId: string } };
12	
13	type RegionAwareEntry = {
14	  // Index signature deliberately widens this past a TS "weak type" (all-optional, no
15	  // index signature) — without it, a concrete Contentful entry's `sys: {id, contentType}`
16	  // shares zero properties with `{updatedAt?}` and fails the generic constraint check below,
17	  // even though it's exactly the shape this utility exists to accept.
18	  sys?: { updatedAt?: string; [key: string]: unknown };
19	  fields: { regions?: ReadonlyArray<RegionRef> };
20	};
21	
22	const isEligible = (entry: RegionAwareEntry, siteId: string): boolean => {
23	  const regions = entry.fields.regions;
24	  if (!regions || regions.length === 0) return true;
25	  return regions.some((region) => region.fields.siteId === siteId);
26	};
27	
28	/** Fewer regions = more specific. Global/unscoped (empty or omitted) sorts last. */
29	const specificity = (entry: RegionAwareEntry): number =>
30	  entry.fields.regions && entry.fields.regions.length > 0 ? entry.fields.regions.length : Infinity;
31	
32	/**
33	 * Inclusive filter — every entry eligible for `siteId` is kept, no precedence applied.
34	 * Use for arrays where multiple non-conflicting regional entries can legitimately
35	 * coexist in the same rendered list (e.g. links inside a shared footerNavGroup).
36	 */
37	export function filterByRegion<T extends RegionAwareEntry>(entries: readonly T[], siteId: string): T[] {
38	  return entries.filter((entry) => isEligible(entry, siteId));
39	}
40	
41	/**
42	 * Single-winner resolution — picks the most specific entry eligible for `siteId`. Use
43	 * for a root entry where only one should render (e.g. which footerConfig to use for
44	 * the current site).
45	 *
46	 * A tie between two equally-scoped, non-global entries is an editorial mistake the
47	 * additive-only sync pipeline doesn't prevent (nothing stops two entries both scoping
48	 * to e.g. exactly ['ZimmermannUS']). Resolved deterministically by most-recently-updated,
49	 * then by `sys.id` when those match, rather than by CDA response order — and a console.warn
50	 * fires on every tie, whichever side wins, so the duplicate entry can be cleaned up.
51	 */
52	export function pickMostSpecificByRegion<T extends RegionAwareEntry>(
53	  candidates: readonly T[],
54	  siteId: string,
55	): T | undefined {
56	  const eligible = filterByRegion(candidates, siteId);
57	
58	  let best: T | undefined;
59	  let bestSpecificity = Infinity;
60	
61	  for (const candidate of eligible) {
62	    const candidateSpecificity = specificity(candidate);
63	
64	    if (best === undefined || candidateSpecificity < bestSpecificity) {
65	      best = candidate;
66	      bestSpecificity = candidateSpecificity;
67	      continue;
68	    }
69	
70	    if (candidateSpecificity === bestSpecificity) {
71	      // The warn sits outside the comparison on purpose. It used to live inside the
72	      // most-recently-updated check, which meant it only fired when the candidate happened to be
73	      // newer than the incumbent — so a tie already arriving newest-first, or one where both
74	      // entries share an updatedAt, was resolved silently. The tie itself is the editorial
75	      // mistake worth surfacing, regardless of which side of it wins.
76	      console.warn(
77	        `resolveByRegion: tie between two equally-scoped entries for region "${siteId}" — resolving by most-recently-updated.`,
78	      );
79	
80	      const bestUpdatedAt = best.sys?.updatedAt ?? '';
81	      const candidateUpdatedAt = candidate.sys?.updatedAt ?? '';
82	      // `sys.id` breaks a dead heat. Without it, equal (or absent) timestamps left the winner
83	      // decided by whichever entry the CDA happened to return first — and `getEntries` is called
84	      // with no `order`, so that isn't stable across requests.
85	      const bestId = String(best.sys?.id ?? '');
86	      const candidateId = String(candidate.sys?.id ?? '');
87	      if (
88	        candidateUpdatedAt > bestUpdatedAt ||
89	        (candidateUpdatedAt === bestUpdatedAt && candidateId < bestId)
90	      ) {
91	        best = candidate;
92	      }
93	    }
94	  }
95	
96	  return best;
97	}

