     1	import { useState, useEffect } from 'react';
     2	import { getContentfulConfig } from '../config/contentful';
     3	import type { ContentfulAsset } from '../types/contentful';
     4	
     5	type ContentfulLink = {
     6	  sys: {
     7	    type: 'Link';
     8	    linkType: 'Asset' | 'Entry';
     9	    id: string;
    10	  };
    11	};
    12	
    13	type ContentfulRawEntry = {
    14	  fields: Record<string, ContentfulLink | ContentfulAsset | unknown>;
    15	  [key: string]: unknown;
    16	};
    17	
    18	type ContentfulEntriesResponse = {
    19	  items: ContentfulRawEntry[];
    20	  includes?: {
    21	    Asset?: ContentfulAsset[];
    22	  };
    23	};
    24	
    25	export const useContentfulEntry = <T>(entryId: string, preview = false) => {
    26	  const [data, setData] = useState<T | null>(null);
    27	  const [isLoading, setIsLoading] = useState(true);
    28	  const [error, setError] = useState<Error | null>(null);
    29	
    30	  useEffect(() => {
    31	    const controller = new AbortController();
    32	
    33	    const fetchEntry = async () => {
    34	      const config = getContentfulConfig();
    35	      if (!config.spaceId || !config.accessToken) {
    36	        setError(new Error('Contentful configuration missing'));
    37	        setIsLoading(false);
    38	        return;
    39	      }
    40	
    41	      try {
    42	        const { spaceId, accessToken, previewAccessToken, environment } = config;
    43	        const baseUrl = preview ? 'https://preview.contentful.com' : 'https://cdn.contentful.com';
    44	        const token = preview ? previewAccessToken : accessToken;
    45	
    46	        // Use the search endpoint with sys.id so include=2 resolves linked assets
    47	        const url = `${baseUrl}/spaces/${spaceId}/environments/${environment}/entries?sys.id=${entryId}&access_token=${token}&include=2`;
    48	
    49	        const response = await fetch(url, { signal: controller.signal });
    50	
    51	        if (!response.ok) {
    52	          throw new Error(`Contentful API error: ${response.status}`);
    53	        }
    54	
    55	        const result: ContentfulEntriesResponse = await response.json();
    56	
    57	        // Resolve linked assets into the entry fields
    58	        const item = result.items[0];
    59	        if (!item) {
    60	          throw new Error(`Entry ${entryId} not found`);
    61	        }
    62	        const resolvedItem = { ...item };
    63	        if (item.fields) {
    64	          Object.keys(item.fields).forEach((fieldKey) => {
    65	            const fieldValue = item.fields[fieldKey] as ContentfulLink;
    66	            if (fieldValue?.sys?.type === 'Link' && fieldValue?.sys?.linkType === 'Asset') {
    67	              const linked = result.includes?.Asset?.find((asset) => asset.sys.id === fieldValue.sys.id);
    68	              if (linked) resolvedItem.fields[fieldKey] = linked;
    69	            }
    70	          });
    71	        }
    72	        setData(resolvedItem as T);
    73	      } catch (err) {
    74	        if (err instanceof DOMException && err.name === 'AbortError') return;
    75	        setError(err instanceof Error ? err : new Error('Unknown error'));
    76	      } finally {
    77	        setIsLoading(false);
    78	      }
    79	    };
    80	
    81	    void fetchEntry();
    82	    return () => controller.abort();
    83	  }, [entryId, preview]);
    84	
    85	  return { data, isLoading, error };
    86	};
    87	
