  for (const c of cands) {
    const cs = c.fields.regions.length;
    if (best === undefined || cs < bs) { best = c; bs = cs; continue; }
    if (cs === bs) {
      const bu = best.sys?.updatedAt ?? '', cu = c.sys?.updatedAt ?? '';
      const bi = String(best.sys?.id ?? ''), ci = String(c.sys?.id ?? '');
      if (cu > bu || ((guard ? cu === bu : true) && ci < bi)) best = c;
